module ball_checker (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [5:0] n,\n    input wire [63:0] sizes_flat,\n    output reg result,\n    output reg done\n);\n    localparam [2:0] IDLE  = 3'd0;\n    localparam [2:0] CLEAR = 3'd1;\n    localparam [2:0] MARK  = 3'd2;\n    localparam [2:0] CHECK = 3'd3;\n    localparam [2:0] DONE_ST = 3'd4;\n    reg [255:0] present;\n    reg [5:0] n_reg;\n    reg [63:0] sizes_reg;\n    reg [2:0] state;\n    reg [2:0] index;\n    wire any_three;\n    assign any_three = |(present[254:0] & {present[255:1]} & {present[255:2]});\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 1'b0;\n            done <= 1'b0;\n            present <= 256'd0;\n            n_reg <= 6'd0;\n            sizes_reg <= 64'd0;\n            index <= 3'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 1'b0;\n                    if (start) begin\n                        n_reg <= n;\n                        sizes_reg <= sizes_flat;\n                        state <= CLEAR;\n                    end\n                end\n                CLEAR: begin\n                    present <= 256'd0;\n                    index <= 3'd0;\n                    state <= MARK;\n                end\n                MARK: begin\n                    if (index < n_reg) begin\n                        if (sizes_reg[8*index +: 8] >= 8'd1 && \n                            sizes_reg[8*index +: 8] <= 8'd255) \n                            present[sizes_reg[8*index +: 8]] <= 1'b1;\n                        index <= index + 3'd1;\n                    end else begin\n                        state <= CHECK;\n                    end\n                end\n                CHECK: begin\n                    result <= any_three;\n                    done <= 1'b1;\n                    state <= DONE_ST;\n                end\n                DONE_ST: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule